            v[6] = 1. - t[0];
            v[6] = 7. * v[6] * v[6] * v[6] * v[6] * v[6] * v[6] * t[0];
            v[7] = 1. - t[0];
            v[7] = v[7] * v[7] * v[7] * v[7] * v[7] * v[7] * v[7];
            y[0] = x[49] * v[0] + x[42] * v[1] + x[35] * v[2] + x[28] * v[3] + x[21] * v[4] + x[14] * v[5] + x[7] * v[6] + x[0] * v[7];
